const ISSUE_STATE: ReadonlySet<unknown> = new Set(["open", "goal", "exported", "closed"])
const GOAL_CHANGE: ReadonlySet<unknown> = new Set(["added", "edited", "finished", "dropped"])
const GOAL_STATE: ReadonlySet<unknown> = new Set(["active", "done", "dropped"])
const CHECKIN_STATE: ReadonlySet<unknown> = new Set(["running", "queued", "idle"])
const SESSION_CHANGE: ReadonlySet<unknown> = new Set(["renamed", "promoted", "adopted", "account", "instructions", "seat", "spawned"])
const ACCOUNT_REASON: ReadonlySet<unknown> = new Set(["usage-limit", "fallback"])
const INSTRUCTION_ACTION: ReadonlySet<unknown> = new Set(["items", "body", "removed"])
const ALERT_SOURCE: ReadonlySet<unknown> = new Set(["doctor", "engine"])
const SERVICE_ROLE: ReadonlySet<unknown> = new Set(["librarian", "reviewer", "helper"])
const RULE_VERB: ReadonlySet<unknown> = new Set(["added", "edited", "removed"])
const WORKTREE_REASON: ReadonlySet<unknown> = new Set(["not-merged", "dirty", "manual-handoff", "keep-failed", "other"])
const HOOK_STATE: ReadonlySet<unknown> = new Set(["running", "passed", "failed", "error"])

export function isMergePR(v: unknown): v is MergePR {
  return isRecord(v) &&
    Number.isInteger(v.number) &&
    typeof v.title === "string" &&
    typeof v.url === "string"
}

export function isMergePRList(v: unknown): v is MergePR[] {
  return Array.isArray(v) && v.every((item: unknown) => isMergePR(item))
}

export function isMergeCheckSummary(v: unknown): v is MergeCheckSummary {
  return isRecord(v) &&
    Number.isInteger(v.done) &&
    (v.total === undefined || Number.isInteger(v.total)) &&
    (v.failed === undefined || isStringList(v.failed))
}

export function isMergeCheckSummaryList(v: unknown): v is MergeCheckSummary[] {
  return Array.isArray(v) && v.every((item: unknown) => isMergeCheckSummary(item))
}

export function isInstructionChange(v: unknown): v is InstructionChange {
  return isRecord(v) &&
    typeof v.name === "string" &&
    INSTRUCTION_ACTION.has(v.action) &&
    (v.added === undefined || isStringList(v.added)) &&
    (v.removed === undefined || isStringList(v.removed)) &&
    (v.body === undefined || typeof v.body === "string")
}

export function isInstructionChangeList(v: unknown): v is InstructionChange[] {
  return Array.isArray(v) && v.every((item: unknown) => isInstructionChange(item))
}

export function isWorktreeEvent(v: unknown): v is WorktreeEvent {
  return isRecord(v) &&
    typeof v.owner === "string" &&
    (v.path === undefined || typeof v.path === "string") &&
    (v.branch === undefined || typeof v.branch === "string") &&
    (v.ahead === undefined || Number.isInteger(v.ahead)) &&
    (v.dirty === undefined || isStringList(v.dirty)) &&
    WORKTREE_REASON.has(v.reason) &&
    (v.detail === undefined || typeof v.detail === "string")
}

export function isHookEvent(v: unknown): v is HookEvent {
  return isRecord(v) &&
    typeof v.runId === "string" &&
    typeof v.repo === "string" &&
    typeof v.hook === "string" &&
    typeof v.event === "string" &&
    (v.label === undefined || typeof v.label === "string") &&
    (v.command === undefined || typeof v.command === "string") &&
    HOOK_STATE.has(v.state) &&
    (v.durationMs === undefined || Number.isInteger(v.durationMs)) &&
    (v.detail === undefined || typeof v.detail === "string")
}

export function isIssueEvent(v: unknown): v is IssueEvent {
  return isRecord(v) &&
    ISSUE_CHANGE.has(v.type) &&
    (v.issueId === undefined || typeof v.issueId === "string") &&
    Number.isInteger(v.number) &&
    typeof v.title === "string" &&
    (v.files === undefined || Array.isArray(v.files) && v.files.every((item: unknown) => (isRecord(item) && typeof item.path === "string" && (item.line === undefined || Number.isInteger(item.line))))) &&
    (v.symbols === undefined || isStringList(v.symbols)) &&
    (v.cost === undefined || typeof v.cost === "string") &&
    (v.direction === undefined || typeof v.direction === "string") &&
    ISSUE_STATE.has(v.state) &&
    typeof v.filer === "string" &&
    (v.actor === undefined || typeof v.actor === "string") &&
    (v.assignee === undefined || typeof v.assignee === "string") &&
    (v.closedBy === undefined || (isRecord(v.closedBy) && (v.closedBy.pr === undefined || Number.isInteger(v.closedBy.pr)) && (v.closedBy.commit === undefined || typeof v.closedBy.commit === "string"))) &&
    (v.reason === undefined || typeof v.reason === "string") &&
    (v.detail === undefined || typeof v.detail === "string")
}

export function isGoalEvent(v: unknown): v is GoalEvent {
  return isRecord(v) &&
    GOAL_CHANGE.has(v.type) &&
    typeof v.goalId === "string" &&
    typeof v.title === "string" &&
    typeof v.actor === "string" &&
    GOAL_STATE.has(v.state) &&
    (v.summary === undefined || typeof v.summary === "string")
}

export function isCheckinEvent(v: unknown): v is CheckinEvent {
  return isRecord(v) &&
    typeof v.parent === "string" &&
    Number.isInteger(v.windowStart) &&
    (isRecord(v.counts) && Number.isInteger(v.counts.running) && Number.isInteger(v.counts.queued) && Number.isInteger(v.counts.idle)) &&
    Array.isArray(v.children) && v.children.every((item: unknown) => (isRecord(item) && typeof item.name === "string" && CHECKIN_STATE.has(item.state) && typeof item.age === "string" && typeof item.goal === "string" && typeof item.pr === "string")) &&
    (v.detail === undefined || typeof v.detail === "string")
}

export function isSlowTestEvent(v: unknown): v is SlowTestEvent {
  return isRecord(v) &&
    typeof v.run === "string" &&
    Number.isInteger(v.count) &&
    Array.isArray(v.crossings) && v.crossings.every((item: unknown) => (isRecord(item) && typeof item.test === "string" && (item.package === undefined || typeof item.package === "string") && (item.features === undefined || isStringList(item.features)) && Number.isInteger(item.durationMs) && typeof item.run === "string" && Number.isInteger(item.otherMs) && typeof item.otherRun === "string" && Number.isInteger(item.limitMs))) &&
    (v.detail === undefined || typeof v.detail === "string")
}

export function isRuleEvent(v: unknown): v is RuleEvent {
  return isRecord(v) &&
    typeof v.ruleId === "string" &&
    typeof v.scope === "string" &&
    typeof v.actor === "string" &&
    RULE_VERB.has(v.verb) &&
    (v.text === undefined || typeof v.text === "string")
}

export function isMergeEvent(v: unknown): v is MergeEvent {
  return isRecord(v) &&
    MERGE_STEP.has(v.type) &&
    typeof v.trialId === "string" &&
    typeof v.repo === "string" &&
    typeof v.base === "string" &&
    isMergePRList(v.prs) &&
    (v.checks === undefined || isMergeCheckSummary(v.checks)) &&
    (v.commit === undefined || typeof v.commit === "string") &&
    (v.reason === undefined || typeof v.reason === "string") &&
    (v.summary === undefined || typeof v.summary === "string") &&
    (v.label === undefined || typeof v.label === "string") &&
    (v.key === undefined || typeof v.key === "string") &&
    (v.detail === undefined || typeof v.detail === "string")
}

export function isMergeDecisionEvent(v: unknown): v is MergeDecisionEvent {
  return isRecord(v) &&
    typeof v.note === "string"
}

export function isMachineEvent(v: unknown): v is MachineEvent {
  return isRecord(v) &&
    typeof v.name === "string" &&
    Number.isInteger(v.freeBytes) &&
    Number.isInteger(v.floorBytes) &&
    typeof v.summary === "string" &&
    Number.isInteger(v.atMs)
}

export function isPREvent(v: unknown): v is PREvent {
  return isRecord(v) &&
    P_R_TYPE.has(v.type) &&
    typeof v.label === "string" &&
    typeof v.location === "string" &&
    (v.number === undefined || Number.isInteger(v.number)) &&
    typeof v.changeId === "string" &&
    (v.key === undefined || typeof v.key === "string") &&
    (v.repo === undefined || typeof v.repo === "string") &&
    (v.title === undefined || typeof v.title === "string") &&
    (v.head === undefined || typeof v.head === "string") &&
    (v.url === undefined || typeof v.url === "string") &&
    (v.branch === undefined || typeof v.branch === "string") &&
    (v.ciAttempt === undefined || Number.isInteger(v.ciAttempt)) &&
    (v.ciMax === undefined || Number.isInteger(v.ciMax)) &&
    (v.summary === undefined || typeof v.summary === "string") &&
    (v.commenter === undefined || typeof v.commenter === "string") &&
    (v.commentId === undefined || typeof v.commentId === "string") &&
    (v.verdict === undefined || typeof v.verdict === "string") &&
    (v.detail === undefined || typeof v.detail === "string") &&
    (v.logTail === undefined || typeof v.logTail === "string") &&
    (v.dropped === undefined || Number.isInteger(v.dropped))
}

export function isSessionEvent(v: unknown): v is SessionEvent {
  return isRecord(v) &&
    SESSION_CHANGE.has(v.type) &&
    typeof v.session === "string" &&
    (v.name === undefined || typeof v.name === "string") &&
    (v.oldName === undefined || typeof v.oldName === "string") &&
    (v.from === undefined || typeof v.from === "string") &&
    (v.to === undefined || typeof v.to === "string") &&
    (v.reason === undefined || ACCOUNT_REASON.has(v.reason)) &&
    (v.profile === undefined || typeof v.profile === "string") &&
    (v.dir === undefined || typeof v.dir === "string") &&
    (v.seat === undefined || typeof v.seat === "string") &&
    (v.sections === undefined || isInstructionChangeList(v.sections)) &&
    (v.detail === undefined || typeof v.detail === "string")
}

export function isAlertEvent(v: unknown): v is AlertEvent {
  return isRecord(v) &&
    ALERT_SOURCE.has(v.source) &&
    (v.reportId === undefined || typeof v.reportId === "string") &&
    (v.trigger === undefined || typeof v.trigger === "string") &&
    (v.summary === undefined || typeof v.summary === "string") &&
    (v.action === undefined || typeof v.action === "string") &&
    (v.detail === undefined || typeof v.detail === "string")
}

export function isServiceFailedEvent(v: unknown): v is ServiceFailedEvent {
  return isRecord(v) &&
    SERVICE_ROLE.has(v.service) &&
    typeof v.session === "string" &&
    (v.turn === undefined || Number.isInteger(v.turn)) &&
    typeof v.error === "string" &&
    (v.profile === undefined || typeof v.profile === "string") &&
    (v.model === undefined || typeof v.model === "string")
}

export function isEngineEvent(v: unknown): v is EngineEvent {
  return isRecord(v) &&
    Number.isInteger(v.minutes) &&
    (v.detail === undefined || typeof v.detail === "string")
}

export function isQuestionEvent(v: unknown): v is QuestionEvent {
  return isRecord(v) &&
    typeof v.questionId === "string" &&
    typeof v.post === "string" &&
    (v.by === undefined || typeof v.by === "string") &&
    (v.reason === undefined || typeof v.reason === "string") &&
    (v.detail === undefined || typeof v.detail === "string")
}

export function isEventPayload(family: string | undefined, type: string | undefined, v: unknown): v is EventPayload {
  if (family === "worktree" && type === "kept") return isWorktreeEvent(v)
  if (family === "hook" && type === "started") return isHookEvent(v)
  if (family === "hook" && type === "result") return isHookEvent(v)
  if (family === "issue" && type === "filed") return isIssueEvent(v)
  if (family === "issue" && type === "updated") return isIssueEvent(v)
  if (family === "issue" && type === "closed") return isIssueEvent(v)
  if (family === "goal" && type === "added") return isGoalEvent(v)
  if (family === "goal" && type === "edited") return isGoalEvent(v)
  if (family === "goal" && type === "finished") return isGoalEvent(v)
  if (family === "goal" && type === "dropped") return isGoalEvent(v)
  if (family === "checkin" && type === "summary") return isCheckinEvent(v)
  if (family === "ci-health" && type === "slow-test") return isSlowTestEvent(v)
  if (family === "rule" && type === "changed") return isRuleEvent(v)
  if (family === "merge" && type === "queued") return isMergeEvent(v)
  if (family === "merge" && type === "trial") return isMergeEvent(v)
  if (family === "merge" && type === "checks") return isMergeEvent(v)
  if (family === "merge" && type === "landed") return isMergeEvent(v)
  if (family === "merge" && type === "failed") return isMergeEvent(v)
  if (family === "merge" && type === "returned") return isMergeEvent(v)
  if (family === "merge" && type === "conflict") return isMergeEvent(v)
  if (family === "merge" && type === "rolled-back") return isMergeEvent(v)
  if (family === "merge" && type === "decision") return isMergeDecisionEvent(v)
  if (family === "machine" && type === "low-disk") return isMachineEvent(v)
  if (family === "pr" && type === "opened") return isPREvent(v)
  if (family === "pr" && type === "ready") return isPREvent(v)
  if (family === "pr" && type === "approved") return isPREvent(v)
  if (family === "pr" && type === "changes") return isPREvent(v)
  if (family === "pr" && type === "ci-failed") return isPREvent(v)
  if (family === "pr" && type === "ci-paused") return isPREvent(v)
  if (family === "pr" && type === "ci-passed") return isPREvent(v)
  if (family === "pr" && type === "returned") return isPREvent(v)
  if (family === "pr" && type === "merged") return isPREvent(v)
  if (family === "pr" && type === "closed") return isPREvent(v)
  if (family === "pr" && type === "comment") return isPREvent(v)
  if (family === "pr" && type === "held-comment") return isPREvent(v)
  if (family === "pr" && type === "review-assigned") return isPREvent(v)
  if (family === "pr" && type === "update") return isPREvent(v)
  if (family === "session" && type === "renamed") return isSessionEvent(v)
  if (family === "session" && type === "promoted") return isSessionEvent(v)
  if (family === "session" && type === "adopted") return isSessionEvent(v)
  if (family === "session" && type === "account") return isSessionEvent(v)
  if (family === "session" && type === "instructions") return isSessionEvent(v)
  if (family === "session" && type === "seat") return isSessionEvent(v)
  if (family === "session" && type === "spawned") return isSessionEvent(v)
  if (family === "alert" && type === "doctor") return isAlertEvent(v)
  if (family === "alert" && type === "engine") return isAlertEvent(v)
  if (family === "service" && type === "failed") return isServiceFailedEvent(v)
  if (family === "engine" && type === "root-flush") return isEngineEvent(v)
  if (family === "question" && type === "withdrawn") return isQuestionEvent(v)
  return false
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v)
}

function isStringList(v: unknown): v is string[] {
  return Array.isArray(v) && v.every((item: unknown) => typeof item === "string")
}
function isNumberList(v: unknown): v is number[] {
  return Array.isArray(v) && v.every((item: unknown) => Number.isInteger(item))
}
